package com.learnagent.skill;
import com.learnagent.agent.AgentExecutionTracker;import com.learnagent.knowledge.KnowledgeSource;import com.learnagent.websearch.WebSearchProvider;import java.time.Instant;import java.util.*;import org.springframework.ai.tool.annotation.*;import org.springframework.stereotype.Component;
@Component public class WebSearchSkill{private final WebSearchProvider provider;private final AgentExecutionTracker tracker;public WebSearchSkill(WebSearchProvider provider,AgentExecutionTracker tracker){this.provider=provider;this.tracker=tracker;}@Tool(description="Search public web sources when current information or material beyond the course knowledge base is needed. Do not call for every request.")public List<WebResult> searchWeb(@ToolParam(description="Focused external search query")String query,@ToolParam(description="Number of sources from 1 to 10",required=false)Integer limit){return tracker.execute("Web Search Skill","searchWeb",()->{List<WebSearchProvider.WebSearchResult> results=provider.search(query,limit==null?5:limit);tracker.addSources(results.stream().map(item->KnowledgeSource.web(item.title(),item.url(),item.sourceName(),item.snippet())).toList());return results.stream().map(item->new WebResult(item.title(),item.snippet(),item.url(),item.sourceName(),item.publishedAt())).toList();},values->"Retrieved "+values.size()+" external sources");}public record WebResult(String title,String snippet,String url,String sourceName,Instant publishedAt){}
}
